messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const FINISH_LINE_Z = 80;
        const START_Z = -60;
        const LANE_WIDTH = 4;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 500);
        camera.position.set(0, 12, 10);
        camera.lookAt(0, 0, 20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 200;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- Environment (Ground & Track) ---
        const groundGeo = new THREE.PlaneGeometry(200, 300);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track markings
        const trackGeo = new THREE.PlaneGeometry(12, 300);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(12, 2);
        // Create a checkerboard texture for the finish line
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, 64, 64);
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, 32, 32);
        ctx.fillRect(32, 32, 32, 32);
        const texture = new THREE.CanvasTexture(canvas);
        texture.magFilter = THREE.NearestFilter;

        const finishMat = new THREE.MeshStandardMaterial({ map: texture });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, FINISH_LINE_Z);
        scene.add(finishLine);

        // Finish Line Posts
        const postGeo = new THREE.CylinderGeometry(0.2, 0.2, 5);
        const postMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const postL = new THREE.Mesh(postGeo, postMat);
        postL.position.set(-6, 2.5, FINISH_LINE_Z);
        scene.add(postL);
        const postR = new THREE.Mesh(postGeo, postMat);
        postR.position.set(6, 2.5, FINISH_LINE_Z);
        scene.add(postR);

        // --- Car Creation ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Main Body
            const bodyGeo = new THREE.BoxGeometry(2, 0.8, 4.5);
            const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.2, metalness: 0.3 });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 0.6;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.6, 0.6, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.3;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const wheelPositions = [
                { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
                { x: -1.1, z: -1.5 }, { x: 1.1, z: -1.5 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler
            const spoilerGeo = new THREE.BoxGeometry(2.2, 0.1, 0.5);
            const spoiler = new THREE.Mesh(spoilerGeo, bodyMat);
            spoiler.position.set(0, 1.2, -2);
            carGroup.add(spoiler);

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        redCar.position.set(-LANE_WIDTH, 0, START_Z);
        scene.add(redCar);

        const blueCar = createCar(0x0000ff);
        blueCar.position.set(LANE_WIDTH, 0, START_Z);
        scene.add(blueCar);

        // --- Animation State ---
        let raceStartTime = 0;
        let isRacing = true;
        let resetTriggered = false;

        // --- Animation Loop ---
        function animate(time) {
            requestAnimationFrame(animate);

            const now = time * 0.001; // seconds

            if (isRacing) {
                // Calculate race duration (seconds)
                const raceDuration = 5.0; 

                // Progress 0.0 to 1.0
                let progress = Math.min((now - raceStartTime) / raceDuration, 1.0);

                if (progress >= 1.0) {
                    // Finish line crossed
                    isRacing = false;
                    resetTriggered = true;
                } else {
                    // Calculate positions based on progress
                    // Total distance to cover
                    const totalDist = FINISH_LINE_Z - START_Z;

                    // Blue Car: Steady speed (Linear)
                    // Blue starts ahead, maintains constant velocity
                    const blueSpeed = 0.2; // units per frame roughly, adjusted for time
                    // Actually let's use the progress logic relative to total distance
                    // Blue car finishes exactly at 1.0 progress
                    const blueZ = START_Z + (totalDist * progress);

                    // Red Car: Acceleration curve
                    // Red starts behind, accelerates to catch up and win slightly before blue finishes
                    // Using an ease-in-out cubic that shifts the finish time slightly earlier than blue
                    // Let's say Red finishes at 0.95 progress relative to the time blue takes.

                    // Red's speed factor: starts slow, ends fast.
                    // We want Red to reach FINISH_LINE_Z slightly before Blue does.
                    // Let's define Red's progress based on a function.

                    // Red logic:
                    // t = 0 -> z = Start
                    // t = 1 -> z = Finish (but we want it to win, so maybe it arrives earlier in the timeline?)
                    // Actually, simpler: Just define Z positions directly.

                    // Blue Z: Linear interpolation from Start to Finish
                    const blueTargetZ = START_Z + (totalDist * progress);

                    // Red Z: Needs to overtake.
                    // Let's use a cubic ease-in for Red.
                    // Red moves faster at the end.
                    // We want Red to win.

                    // Let's calculate Red's Z based on a custom curve.
                    // At progress 0.5 (mid race), Red should be at roughly 60% of the track.
                    // At progress 1.0, Red should be at Finish.
                    // Wait, if Red wins, Red should be at Finish BEFORE Blue.
                    // So Red's Z should reach Finish_Line_Z when progress < 1.0.

                    // Let's invert the logic slightly:
                    // We drive the animation by a "Global Race Time".
                    // Blue reaches Finish at Global Time T.
                    // Red reaches Finish at Global Time T * 0.9 (wins).

                    const globalTime = progress; // 0 to 1

                    // Blue: Linear 0 -> 1
                    const bluePos = THREE.MathUtils.lerp(START_Z, FINISH_LINE_Z, globalTime);

                    // Red: Cubic Ease In (starts slow, goes fast)
                    // We want Red to reach FINISH_LINE_Z at globalTime = 0.95
                    // So we map globalTime 0..0.95 to Red's 0..1 progress?
                    // No, let's just calculate Red's Z directly.

                    // Red's "internal progress"
                    // We want Red to finish at globalTime = 0.9
                    const redFinishTime = 0.92; 

                    if (globalTime <= redFinishTime) {
                        // Red is still racing
                        // Ease-in function: x^3
                        let t = globalTime / redFinishTime; // 0 to 1
                        let easedT = t * t * t; // 0 to 1

                        // Red Z
                        const redZ = THREE.MathUtils.lerp(START_Z, FINISH_LINE_Z, easedT);
                        redCar.position.z = redZ;
                    } else {
                        // Red has finished, hold at finish line
                        redCar.position.z = FINISH_LINE_Z;
                    }

                    blueCar.position.z = bluePos;
                }
            } else {
                // Resetting logic
                if (resetTriggered) {
                    // Wait a moment then reset
                    setTimeout(() => {
                        redCar.position.z = START_Z;
                        blueCar.position.z = START_Z;
                        raceStartTime = performance.now() * 0.001;
                        isRacing = true;
                        resetTriggered = false;
                    }, 500);
                }
            }

            // Camera Follow Logic
            // Target position is roughly halfway between the two cars, slightly ahead of the leading car
            const leadCarZ = Math.max(redCar.position.z, blueCar.position.z);

            // Smoothly interpolate camera Z
            const targetCamZ = leadCarZ + 15;
            const targetCamX = 0; // Keep centered horizontally

            camera.position.z += (targetCamZ - camera.position.z) * 0.05;
            camera.position.x += (targetCamX - camera.position.x) * 0.05;

            // Look at a point slightly ahead of the cars
            const lookAtZ = leadCarZ + 10;
            camera.lookAt(0, 0.5, lookAtZ);

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Race
        raceStartTime = performance.now() * 0.001;
        animate(performance.now());

    </script>
</body>
</html>
```
